insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$santo-antonio-de-leverger$q$, $q$https://transparencia.leverger.mt.gov.br/Legislacao/Leis/Lei-14282023-1315 (Lei 1.428/2023; PDF https://transparencia.leverger.mt.gov.br/fotos_documentos/1319.pdf) ; https://www.diariomunicipal.com.br/amm-mt/materia/640B5EF0 (Lei 1.095/2013) ; https://www.diariomunicipal.com.br/amm-mt/materia/B93921BB (Decreto 33/2013) ; https://www.diariomunicipal.com.br/amm-mt/materia/508BC65C (Decreto 53/2014) ; https://www.diariomunicipal.com.br/amm-mt/materia/0A544CED (Decreto 06/2012)$q$, $q$Atos oficiais do Município de Santo Antônio de Leverger: domínio público (Lei 9.610/1998 art. 8º IV). Geometria derivada do OpenStreetMap (ODbL 1.0, © colaboradores do OpenStreetMap), pelos nomes das vias.$q$, 8, $q$Uma regra ativa (Lei 1.428/2023, vias nomeadas, confiança média) e três registros desativados (ZRM da Lei 1.095/2013 em dois escalões de PBT, perímetro só em mapa anexo; Decreto 06/2012 provisório). A Lei 1.428/2023 é ambígua entre PBT e carga nas 20 t: adotada a leitura menos restritiva (3 eixos ou mais E PBT acima de 20 t).$q$);
